const COMMANDS = [
// ===== File & Directory =====
{cat:"file",cmd:"ls",desc:"List directory contents",detail:"Displays files and directories in the current or specified path. Supports flags for hidden files (-a), long format (-l), human-readable sizes (-h), and sorting (-t by time).",ex:[["ls -lah /home","List all files (including hidden) in long format with human-readable sizes"],["ls -lt *.txt","List .txt files sorted by modification time"]],tags:"list,dir"},
{cat:"file",cmd:"cd",desc:"Change directory",detail:"Navigates between directories in the file system. Use 'cd ~' for home, 'cd ..' for parent, 'cd -' for previous directory.",ex:[["cd /var/log","Change to /var/log directory"],["cd ..","Go up one level to parent directory"],["cd ~","Go to home directory"]],tags:"navigate"},
{cat:"file",cmd:"pwd",desc:"Print working directory",detail:"Outputs the absolute path of the current directory. Useful in scripts to know your location.",ex:[["pwd","Print the current directory path"]],tags:"path"},
{cat:"file",cmd:"mkdir",desc:"Create directories",detail:"Creates new directories. The -p flag creates parent directories as needed without errors if they exist.",ex:[["mkdir -p projects/src/main","Create nested directories (creates parents as needed)"],["mkdir new_folder","Create a single new directory"]],tags:"create,dir"},
{cat:"file",cmd:"rmdir",desc:"Remove empty directories",detail:"Deletes directories only if they are empty. For non-empty dirs, use 'rm -r' instead.",ex:[["rmdir empty_folder","Remove an empty directory (fails if not empty)"]],tags:"remove,dir"},
{cat:"file",cmd:"rm",desc:"Remove files or directories",detail:"Deletes files or directories permanently. -r for recursive, -f for force (no prompt), -i for interactive confirmation. Use with caution!",ex:[["rm -rf old_project","Force-remove a directory and all contents recursively"],["rm *.tmp","Delete all .tmp files in current directory"],["rm -i important.txt","Delete with confirmation prompt before removal"]],tags:"delete,remove"},
{cat:"file",cmd:"cp",desc:"Copy files and directories",detail:"Copies files or directories. -r for recursive (directories), -i for interactive prompt, -v for verbose output.",ex:[["cp -r src/ dest/","Recursively copy entire src/ directory to dest/"],["cp file.txt backup.txt","Copy a single file to backup.txt"],["cp -i *.txt /backup/","Copy all .txt files, prompt before overwriting"]],tags:"copy"},
{cat:"file",cmd:"mv",desc:"Move or rename files",detail:"Moves files to a new location or renames them. -v for verbose, -i to prompt before overwrite.",ex:[["mv old.txt new.txt","Rename old.txt to new.txt"],["mv file.txt /tmp/","Move file.txt into /tmp/ directory"],["mv -v *.log logs/","Move all .log files to logs/, show what's being moved"]],tags:"move,rename"},
{cat:"file",cmd:"touch",desc:"Create empty files or update timestamps",detail:"Creates empty files if they don't exist, or updates modification/access timestamps of existing files.",ex:[["touch newfile.txt","Create an empty file called newfile.txt"],["touch -t 202601010000 file.txt","Set file timestamp to Jan 1, 2026 00:00"]],tags:"create"},
{cat:"file",cmd:"find",desc:"Search for files in a directory hierarchy",detail:"Powerful file search by name, type, size, modification time, permissions, and more. Supports exec to run commands on results.",ex:[["find / -name '*.conf'","Find all .conf files on entire system"],["find . -type f -size +100M","Find files larger than 100MB in current dir"],["find /var -mtime -1","Find files modified in the last 24 hours under /var"]],tags:"search"},
{cat:"file",cmd:"locate",desc:"Find files by name (uses database)",detail:"Fast file search using a pre-built database. Run 'updatedb' to refresh. Much faster than find for name-only searches.",ex:[["locate nginx.conf","Quickly find nginx.conf anywhere on system"],["locate -i readme","Case-insensitive search for readme files"]],tags:"search,fast"},
{cat:"file",cmd:"tree",desc:"Display directory tree structure",detail:"Shows directory contents in a visual tree format. -L limits depth, -a shows hidden files, --dirsfirst lists dirs before files.",ex:[["tree -L 2","Show directory tree up to 2 levels deep"],["tree -a --dirsfirst","Show all files including hidden, directories first"]],tags:"visualize"},
{cat:"file",cmd:"stat",desc:"Display file or file system status",detail:"Shows detailed metadata: size, blocks, inode, access/modify/change times, and permissions.",ex:[["stat file.txt","Show detailed metadata of file.txt"],["stat -f /","Show filesystem status of root partition"]],tags:"info,metadata"},
{cat:"file",cmd:"file",desc:"Determine file type",detail:"Identifies file type by examining content (not extension). Detects text, binary, archive, image types and more.",ex:[["file document.pdf","Identify the actual file type of document.pdf"],["file *.png","Identify types of all .png files"]],tags:"type,info"},
{cat:"file",cmd:"ln",desc:"Create hard and symbolic links",detail:"Creates links between files. -s for symbolic (soft) links, without -s creates hard links. Symlinks point to path, hardlinks share inode.",ex:[["ln -s /var/www html","Create a symbolic link 'html' pointing to /var/www"],["ln target.txt hardlink.txt","Create a hard link (shares same inode)"]],tags:"symlink,link"},
{cat:"file",cmd:"rename",desc:"Rename multiple files",detail:"Batch renames files using Perl regex. Powerful for pattern-based renaming of many files at once.",ex:[["rename 's/\\.old/.new/' *.old","Rename all .old files to .new"],["rename 'y/A-Z/a-z/' *.TXT","Convert all .TXT filenames to lowercase"]],tags:"batch,rename"},
{cat:"file",cmd:"du",desc:"Estimate file and directory space usage",detail:"Reports disk space used by files/directories. -s for summary, -h for human-readable, --max-depth limits recursion.",ex:[["du -sh /home","Show total size of /home in human-readable format"],["du -h --max-depth=1","Show size of each subdirectory one level deep"],["du -a | sort -n","List all files by size, sorted ascending"]],tags:"size,disk"},
{cat:"file",cmd:"df",desc:"Report file system disk space usage",detail:"Shows available/used disk space on mounted filesystems. -h for human-readable, -i for inode info, --type filters filesystem type.",ex:[["df -h","Show disk space for all mounted filesystems (human-readable)"],["df -h --type=ext4","Show only ext4 filesystems"],["df -i","Show inode usage instead of block usage"]],tags:"disk,space"},

// ===== File Content / Text =====
{cat:"text",cmd:"cat",desc:"Concatenate and display file content",detail:"Displays file contents, concatenates multiple files, or writes to files via redirection. -n adds line numbers.",ex:[["cat file.txt","Display the entire contents of file.txt"],["cat -n file.txt","Display file.txt with line numbers"],["cat > newfile.txt","Type content into newfile.txt (Ctrl+D to save)"]],tags:"view,concat"},
{cat:"text",cmd:"less",desc:"View file content page by page",detail:"Pager for viewing large files interactively. Supports search (/pattern), navigation, and follow mode (+F like tail -f).",ex:[["less largefile.log","Open largefile.log in interactive pager"],["less +F /var/log/syslog","Open syslog in follow mode (like tail -f)"]],tags:"view,pager"},
{cat:"text",cmd:"more",desc:"View file content page by page",detail:"Simple pager for viewing files one screen at a time. Less feature-rich than 'less' but available everywhere.",ex:[["more file.txt","View file.txt one screen at a time"]],tags:"view,pager"},
{cat:"text",cmd:"head",desc:"Output the first part of files",detail:"Shows the first lines of a file. -n for line count, -c for byte count. Useful for previewing file starts.",ex:[["head -n 20 file.txt","Show the first 20 lines of file.txt"],["head -c 1000 binary.dat","Show the first 1000 bytes of binary.dat"]],tags:"view,top"},
{cat:"text",cmd:"tail",desc:"Output the last part of files",detail:"Shows the last lines of a file. -f follows file growth (live logs), -n sets line count. Essential for log monitoring.",ex:[["tail -n 50 log.txt","Show the last 50 lines of log.txt"],["tail -f /var/log/syslog","Continuously follow syslog as new lines are added"],["tail -f --pid=$$ file","Follow file until current process exits"]],tags:"view,bottom,follow"},
{cat:"text",cmd:"grep",desc:"Search text using patterns",detail:"Searches for text patterns in files or input. -r recursive, -i case-insensitive, -v invert match, -E extended regex, -n line numbers.",ex:[["grep -rn 'error' /var/log","Recursively search for 'error' in /var/log with line numbers"],["grep -i 'warning' file.txt","Case-insensitive search for 'warning'"],["grep -v '#' config.conf","Show lines that do NOT contain '#'"],["grep -E 'foo|bar' file","Search for either 'foo' or 'bar' (extended regex)"]],tags:"search,filter"},
{cat:"text",cmd:"egrep",desc:"Extended grep (grep -E)",detail:"Alias for grep -E. Supports extended regex without escaping (|, +, ?, etc). Deprecated in favor of 'grep -E'.",ex:[["egrep 'foo|bar' file.txt","Search for 'foo' OR 'bar' in file.txt"]],tags:"search,regex"},
{cat:"text",cmd:"sed",desc:"Stream editor for text transformation",detail:"Non-interactive text editor for find-replace, deletion, insertion. -i edits in-place, 's/old/new/g' substitutes globally.",ex:[["sed 's/old/new/g' file.txt","Replace all 'old' with 'new' in file.txt (output only)"],["sed -i 's/foo/bar/g' *.conf","Replace foo with bar in all .conf files in-place"],["sed -n '5,10p' file.txt","Print only lines 5 through 10 of file.txt"]],tags:"edit,replace"},
{cat:"text",cmd:"awk",desc:"Pattern scanning and text processing",detail:"Powerful text processing tool. Processes line by line, splits into fields ($1, $2...), supports conditions, math, and formatting.",ex:[["awk '{print $2}' file.txt","Print the 2nd column of every line"],["awk -F: '{print $1}' /etc/passwd","Print usernames (1st field, colon-separated)"],["awk 'NR>1 && $3>100' data.csv","Print rows after header where 3rd column > 100"]],tags:"process,column"},
{cat:"text",cmd:"sort",desc:"Sort lines of text files",detail:"Sorts lines alphabetically or numerically. -n numeric, -r reverse, -u unique, -t delimiter, -k field number.",ex:[["sort file.txt","Sort lines alphabetically"],["sort -r -n numbers.txt","Sort numbers in descending order"],["sort -u -t: -k3 /etc/passwd","Sort by 3rd field (UID), remove duplicates, colon delimiter"]],tags:"sort"},
{cat:"text",cmd:"uniq",desc:"Report or omit repeated lines",detail:"Removes or reports duplicate adjacent lines. Must be used after sort for full deduplication. -c counts occurrences.",ex:[["sort file | uniq","Remove duplicate lines (must sort first)"],["sort file | uniq -c | sort -rn","Count occurrences of each line, sorted by frequency"]],tags:"deduplicate"},
{cat:"text",cmd:"cut",desc:"Remove sections from each line",detail:"Extracts fields or characters from each line. -d delimiter, -f field number, -c character range.",ex:[["cut -d: -f1 /etc/passwd","Extract 1st field (username) using colon delimiter"],["cut -c1-10 file.txt","Extract characters 1 through 10 from each line"],["cut -f2 -d',' data.csv","Extract 2nd column from CSV file"]],tags:"extract,column"},
{cat:"text",cmd:"paste",desc:"Merge lines of files",detail:"Combines lines from multiple files side by side. -d sets delimiter, default is tab.",ex:[["paste file1.txt file2.txt","Merge lines from two files side by side (tab-separated)"],["paste -d',' col1.txt col2.txt","Merge two files with comma as delimiter"]],tags:"merge"},
{cat:"text",cmd:"tr",desc:"Translate or delete characters",detail:"Translates characters from one set to another, or deletes them. -d delete, -s squeeze repeats. Works on stdin only.",ex:[["echo 'Hello' | tr 'a-z' 'A-Z'","Convert lowercase to uppercase → HELLO"],["tr -d '\\n' < file.txt","Remove all newline characters from file"],["tr -s ' ' < file.txt","Squeeze multiple spaces into single spaces"]],tags:"translate,replace"},
{cat:"text",cmd:"wc",desc:"Count words, lines, and bytes",detail:"Counts lines (-l), words (-w), characters (-c), or bytes (-m) in a file or input.",ex:[["wc -l file.txt","Count number of lines in file.txt"],["wc -w *.txt","Count words in all .txt files"],["wc -c file.dat","Count bytes in file.dat"]],tags:"count"},
{cat:"text",cmd:"diff",desc:"Compare files line by line",detail:"Shows differences between two files or directories. -u unified format, -r recursive for directories.",ex:[["diff file1.txt file2.txt","Show differences between two files"],["diff -u old.conf new.conf","Show differences in unified format (for patches)"],["diff -r dir1/ dir2/","Recursively compare two directories"]],tags:"compare"},
{cat:"text",cmd:"tee",desc:"Read from stdin and write to stdout and files",detail:"Duplicates stdin to both stdout and files simultaneously. -a appends instead of overwriting. Useful in pipelines.",ex:[["echo 'log' | tee file.txt","Write 'log' to both screen and file.txt"],["cmd | tee -a logfile.txt","Run command, append output to logfile AND show on screen"]],tags:"redirect,duplicate"},
{cat:"text",cmd:"xargs",desc:"Build and execute command lines from stdin",detail:"Takes stdin and uses it as arguments for another command. -n limits args per call, -I for substitution, -p for confirmation.",ex:[["find . -name '*.tmp' | xargs rm","Find all .tmp files and delete them"],["find . -type f | xargs grep 'pattern'","Search for pattern in all files found"],["echo '1 2 3' | xargs -n1 echo","Run echo once per argument (3 times)"]],tags:"pipeline"},
{cat:"text",cmd:"nl",desc:"Number lines of files",detail:"Adds line numbers to each line of output. -ba numbers all lines including blanks.",ex:[["nl file.txt","Display file.txt with line numbers"],["nl -ba file.txt","Number all lines including blank lines"]],tags:"number,lines"},
{cat:"text",cmd:"tac",desc:"Concatenate and print files in reverse",detail:"Like cat but outputs lines in reverse order (last line first).",ex:[["tac file.txt","Display file.txt with lines in reverse order"]],tags:"reverse"},
{cat:"text",cmd:"rev",desc:"Reverse lines character by character",detail:"Reverses each line's characters. 'hello' becomes 'olleh'. Useful for palindrome checks.",ex:[["echo 'hello' | rev","Reverse characters → olleh"]],tags:"reverse"},
{cat:"text",cmd:"fold",desc:"Wrap each input line to fit in specified width",detail:"Wraps long lines to a specified width. -w sets width, -s breaks at word boundaries.",ex:[["fold -w 80 file.txt","Wrap lines at 80 characters width"],["fold -w 40 -s file.txt","Wrap at 40 chars, break at word boundaries"]],tags:"wrap"},
{cat:"text",cmd:"column",desc:"Columnate lists",detail:"Formats input into aligned columns/tables. -t creates table, -s sets delimiter.",ex:[["column -t -s',' data.csv","Format CSV file into aligned table"],["cat /etc/passwd | column -t -s:","Format passwd file into table (colon delimiter)"]],tags:"format,table"},
{cat:"text",cmd:"expand",desc:"Convert tabs to spaces",detail:"Replaces tab characters with spaces. -t sets tab width (default 8).",ex:[["expand -t 4 file.txt","Convert tabs to 4 spaces each"]],tags:"tabs"},
{cat:"text",cmd:"unexpand",desc:"Convert spaces to tabs",detail:"Replaces leading spaces with tabs. -t sets tab width. Opposite of expand.",ex:[["unexpand -t 4 file.txt","Convert leading 4-space groups to tabs"]],tags:"tabs"},

// ===== Permissions & Ownership =====
{cat:"perms",cmd:"chmod",desc:"Change file mode bits",detail:"Sets read/write/execute permissions for owner, group, and others. Use numeric (755) or symbolic (u+x) notation. -R for recursive.",ex:[["chmod 755 script.sh","Set rwxr-xr-x (owner full, others read+execute)"],["chmod +x file","Add execute permission for everyone"],["chmod -R 644 /var/www","Set all files in /var/www to rw-r--r--"],["chmod u+x,g-w file.txt","Add execute for owner, remove write for group"]],tags:"permission"},
{cat:"perms",cmd:"chown",desc:"Change file owner and group",detail:"Changes the owner and/or group of files. -R for recursive. Format: owner:group.",ex:[["chown user:group file.txt","Change owner to 'user' and group to 'group'"],["chown -R www-data:www-data /var/www","Recursively change all files to www-data ownership"]],tags:"owner"},
{cat:"perms",cmd:"chgrp",desc:"Change group ownership",detail:"Changes only the group ownership of files. -R for recursive. Simpler than chown when only group changes.",ex:[["chgrp developers project/","Change group of project/ to 'developers'"],["chgrp -R staff /shared","Recursively set group to 'staff' on /shared"]],tags:"group"},
{cat:"perms",cmd:"umask",desc:"Set default file creation mask",detail:"Sets default permission mask for new files. 022 = 755 dirs/644 files. 077 = 700 dirs/600 files. -S shows symbolic form.",ex:[["umask 022","New files get 644, new dirs get 755 (default)"],["umask 077","New files get 600, new dirs get 700 (secure)"],["umask -S","Show current umask in symbolic form (rwx notation)"]],tags:"default,permission"},
{cat:"perms",cmd:"setfacl",desc:"Set file access control lists",detail:"Sets fine-grained permissions beyond owner/group/other. -m to modify, -R recursive. Allows per-user or per-group permissions.",ex:[["setfacl -m u:john:rwx file.txt","Give user john rwx permission on file"],["setfacl -R -m g:dev:rw /project","Give group dev read-write on entire /project"]],tags:"acl"},
{cat:"perms",cmd:"getfacl",desc:"Get file access control lists",detail:"Displays ACL permissions on files/directories. Shows default ACLs and access ACLs.",ex:[["getfacl file.txt","Show ACL permissions on file.txt"],["getfacl -R /project","Show ACLs for all files in /project recursively"]],tags:"acl"},
{cat:"perms",cmd:"sudo",desc:"Execute a command as superuser",detail:"Runs a single command with root privileges. -u runs as specific user, -i opens root shell. Requires sudoers config.",ex:[["sudo apt update","Run 'apt update' as root"],["sudo -u www-data ls /var/www","Run ls as user www-data"],["sudo -i","Open an interactive root shell"]],tags:"root,admin"},
{cat:"perms",cmd:"su",desc:"Switch user",detail:"Switches to another user's shell entirely. '-' for login shell. Without username, defaults to root.",ex:[["su - username","Switch to username with full login shell"],["su -","Switch to root with login environment"]],tags:"switch,user"},

// ===== Process Management =====
{cat:"process",cmd:"ps",desc:"Report a snapshot of current processes",detail:"Lists running processes. 'aux' shows all users, -ef full format, -eo custom output with --sort option.",ex:[["ps aux","List all running processes (BSD format)"],["ps -ef | grep nginx","Find nginx processes (System V format)"],["ps -eo pid,user,%mem,cmd --sort=-%mem","List processes sorted by memory usage (descending)"]],tags:"list,process"},
{cat:"process",cmd:"top",desc:"Display Linux processes (interactive)",detail:"Real-time interactive process monitor showing CPU, memory, and process stats. -b batch mode, -u filter by user.",ex:[["top","Open interactive process monitor"],["top -c -b -n1","Run once in batch mode with full command lines"],["top -u username","Show only processes belonging to username"]],tags:"monitor,realtime"},
{cat:"process",cmd:"htop",desc:"Interactive process viewer (enhanced top)",detail:"Enhanced version of top with color, scrolling, mouse support, and tree view. -u filters by user, -p by PID.",ex:[["htop","Open enhanced interactive process viewer"],["htop -u root","Show only root's processes"],["htop -p 1234","Monitor specific process by PID"]],tags:"monitor"},
{cat:"process",cmd:"kill",desc:"Send a signal to a process",detail:"Sends signals to processes by PID. Default SIGTERM (15), -9 SIGKILL (force), -TERM for graceful. Use pgrep to find PIDs.",ex:[["kill 1234","Send SIGTERM to process 1234 (graceful)"],["kill -9 1234","Force kill process 1234 (SIGKILL, no cleanup)"],["kill -TERM $(pgrep nginx)","Send SIGTERM to all nginx processes"]],tags:"terminate,signal"},
{cat:"process",cmd:"killall",desc:"Kill processes by name",detail:"Kills processes by their command name (not PID). -9 force kill, -u by user, -e exact match.",ex:[["killall firefox","Kill all Firefox processes by name"],["killall -9 nginx","Force kill all nginx processes"],["killall -u username","Kill all processes owned by username"]],tags:"terminate,name"},
{cat:"process",cmd:"pkill",desc:"Signal processes by pattern",detail:"Sends signals to processes matching a pattern. -f matches full command line, -u by user, -9 for SIGKILL.",ex:[["pkill -f 'python script.py'","Kill process matching full command 'python script.py'"],["pkill -u guest","Kill all processes by user 'guest'"],["pkill -9 sshd","Force kill all sshd processes"]],tags:"kill,pattern"},
{cat:"process",cmd:"pgrep",desc:"Look up processes by name",detail:"Finds process IDs by name or pattern. -u by user, -l shows name, -f matches full command line.",ex:[["pgrep nginx","Find PIDs of all nginx processes"],["pgrep -u root sshd","Find sshd processes owned by root"],["pgrep -l python","Find python processes, show name + PID"]],tags:"find,process"},
{cat:"process",cmd:"jobs",desc:"List active jobs",detail:"Lists background and stopped jobs in the current shell. -l includes PIDs. Use with bg/fg commands.",ex:[["jobs","List background and stopped jobs in current shell"],["jobs -l","List jobs with their process IDs"]],tags:"background"},
{cat:"process",cmd:"bg",desc:"Resume jobs in background",detail:"Resumes a stopped job in the background. Use after Ctrl+Z to continue a process without blocking terminal.",ex:[["bg %1","Resume job #1 in the background"],["Ctrl+Z then bg","Suspend current process, then resume in background"]],tags:"background"},
{cat:"process",cmd:"fg",desc:"Bring jobs to foreground",detail:"Brings a background job to the foreground. %1 refers to job number 1 from jobs list.",ex:[["fg %1","Bring job #1 to the foreground"]],tags:"foreground"},
{cat:"process",cmd:"nohup",desc:"Run command immune to hangups",detail:"Runs a command that continues after terminal close/logout. Output goes to nohup.out by default. Combine with & for background.",ex:[["nohup python script.py &","Run script.py in background, survives logout"],["nohup ./server > log.txt 2>&1 &","Run server, redirect all output to log.txt, background"]],tags:"background,persist"},
{cat:"process",cmd:"screen",desc:"Terminal multiplexer (sessions)",detail:"Creates persistent terminal sessions that survive disconnects. -S names session, -ls lists, -r reattaches.",ex:[["screen -S mysession","Create a named screen session called 'mysession'"],["screen -ls","List all active screen sessions"],["screen -r mysession","Reattach to the 'mysession' screen session"]],tags:"session,multiplex"},
{cat:"process",cmd:"tmux",desc:"Terminal multiplexer (modern)",detail:"Modern terminal multiplexer with split panes, tabs, and detachable sessions. Ctrl+B is prefix key. More capable than screen.",ex:[["tmux new -s work","Create a new tmux session named 'work'"],["tmux ls","List all tmux sessions"],["tmux attach -t work","Attach to the 'work' tmux session"],["Ctrl+B then D","Detach from tmux (session keeps running)"]],tags:"session,multiplex"},
{cat:"process",cmd:"nice",desc:"Run with modified scheduling priority",detail:"Starts a process with adjusted priority. -n sets value (-20 highest to 19 lowest). Default is 0. Lower = higher priority.",ex:[["nice -n 10 ./backup.sh","Run backup.sh with low priority (nice value 10)"],["nice -n -5 high_priority_task","Run task with higher priority (requires root)"]],tags:"priority"},
{cat:"process",cmd:"renice",desc:"Alter priority of running process",detail:"Changes priority of an already running process. -n new value, -p by PID, -u by user. Root needed for negative values.",ex:[["renice -n 5 -p 1234","Lower priority of running process 1234"],["renice +10 -u username","Lower priority of all processes by username"]],tags:"priority"},
{cat:"process",cmd:"time",desc:"Measure command execution time",detail:"Reports real (wall clock), user (CPU), and sys (kernel) time for a command. Useful for benchmarking.",ex:[["time ./script.sh","Measure how long script.sh takes to run"],["time wget url","Measure download time of a URL"]],tags:"benchmark"},
{cat:"process",cmd:"watch",desc:"Execute a command periodically",detail:"Runs a command repeatedly at intervals, showing output full-screen. -n interval seconds, -d highlights changes.",ex:[["watch -n 2 'ls -la'","Run 'ls -la' every 2 seconds, full-screen"],["watch -n 5 df -h","Update disk usage display every 5 seconds"],["watch -d free -m","Monitor memory, highlight changes between updates"]],tags:"monitor,repeat"},

// ===== Networking =====
{cat:"net",cmd:"ping",desc:"Send ICMP echo requests",detail:"Tests network connectivity to a host. -c sets count, -i interval, -W timeout. Measures round-trip time.",ex:[["ping google.com","Continuously ping google.com until Ctrl+C"],["ping -c 4 8.8.8.8","Send exactly 4 ping packets to 8.8.8.8"],["ping -i 2 host.com","Ping every 2 seconds (slower interval)"]],tags:"connectivity,test"},
{cat:"net",cmd:"curl",desc:"Transfer data from URLs",detail:"Versatile HTTP client for URLs. -O save to file, -X set method, -d POST data, -H headers, -L follow redirects. Supports many protocols.",ex:[["curl https://example.com","Fetch and display HTML from example.com"],["curl -O https://site.com/file.zip","Download file.zip keeping original filename"],["curl -X POST -d 'data' https://api.com","Send POST request with data to API"],["curl -H 'Content-Type: application/json' -d '{\"k\":\"v\"}' url","Send JSON POST request with custom header"]],tags:"http,download,api"},
{cat:"net",cmd:"wget",desc:"Non-interactive network downloader",detail:"Downloads files from web. -c resume, -r recursive, -m mirror, -O output file. Better than curl for large/recursive downloads.",ex:[["wget https://site.com/file.zip","Download file.zip from website"],["wget -c url","Resume a partially downloaded file"],["wget -r -l2 https://site.com","Recursively download site up to 2 levels deep"],["wget -m https://site.com","Mirror an entire website"]],tags:"download"},
{cat:"net",cmd:"ssh",desc:"Secure shell remote login",detail:"Securely connects to remote machines. -p custom port, -i key file, -L port forwarding. Essential for remote server management.",ex:[["ssh user@host.com","Log in to host.com as user"],["ssh -p 2222 user@host","Connect on non-default port 2222"],["ssh -i key.pem user@host","Authenticate using a specific private key"],["ssh -L 8080:localhost:80 user@host","Forward local port 8080 to remote port 80 (tunnel)"]],tags:"remote,secure"},
{cat:"net",cmd:"scp",desc:"Secure copy over SSH",detail:"Copies files between local and remote hosts over SSH. -r recursive, -P custom port, -i key file.",ex:[["scp file.txt user@host:/path/","Copy file.txt to remote /path/ directory"],["scp -r dir/ user@host:/dest/","Recursively copy entire directory to remote"],["scp -P 2222 file user@host:.","Copy file using custom SSH port 2222"]],tags:"copy,remote"},
{cat:"net",cmd:"rsync",desc:"Efficient file synchronization",detail:"Syncs files/dirs efficiently by transferring only differences. -a archive mode, -v verbose, -z compress, --delete remove extras on dest.",ex:[["rsync -avz src/ user@host:/dest/","Sync src/ to remote /dest/ with compression"],["rsync -avz --delete src/ dest/","Sync and delete files in dest/ that don't exist in src/"],["rsync -avz -e 'ssh -p 2222' src/ host:/dest/","Sync using custom SSH port 2222"]],tags:"sync,backup"},
{cat:"net",cmd:"netstat",desc:"Network connections and statistics",detail:"Shows network connections, ports, routing tables, interface stats. -t TCP, -l listening, -n numeric, -p process. Deprecated, use ss.",ex:[["netstat -tlnp","List all listening TCP ports with process info"],["netstat -an | grep :80","Find all connections on port 80"],["netstat -rn","Display the routing table (like route -n)"]],tags:"connections,ports"},
{cat:"net",cmd:"ss",desc:"Socket statistics (modern netstat)",detail:"Modern replacement for netstat. Shows socket/connections. -t TCP, -u UDP, -l listening, -p process, -n numeric.",ex:[["ss -tlnp","List listening TCP sockets with process info"],["ss -tulpn","List all TCP and UDP listening ports"],["ss -s","Show a summary of socket statistics"]],tags:"sockets,ports"},
{cat:"net",cmd:"ifconfig",desc:"Configure network interfaces",detail:"Shows or configures network interfaces (IP, netmask, MAC). Deprecated, replaced by 'ip' command but still widely used.",ex:[["ifconfig","Show all network interfaces and their config"],["ifconfig eth0 up","Bring network interface eth0 up (enable)"],["ifconfig eth0 192.168.1.10 netmask 255.255.255.0","Set static IP and netmask on eth0"]],tags:"interface"},
{cat:"net",cmd:"ip",desc:"Show/manipulate routing, devices (modern)",detail:"Modern network configuration tool. addr for IP, route for routing, link for interfaces. Replaces ifconfig and route.",ex:[["ip addr show","Display all IP addresses on all interfaces"],["ip route","Show the routing table"],["ip link set eth0 up","Enable interface eth0"],["ip -s link","Show interface statistics (rx/tx bytes)"]],tags:"interface,routing"},
{cat:"net",cmd:"traceroute",desc:"Trace network path to host",detail:"Shows the hop-by-hop path packets take to a destination. Useful for diagnosing network routing issues.",ex:[["traceroute google.com","Show network path from you to google.com"],["traceroute -n 8.8.8.8","Show path without resolving hostnames (faster)"]],tags:"trace,routing"},
{cat:"net",cmd:"nslookup",desc:"Query DNS records",detail:"Looks up DNS records for domains. Supports different record types (A, MX, NS, CNAME). Interactive mode if no args.",ex:[["nslookup example.com","Look up IP address for example.com"],["nslookup -type=MX domain.com","Look up mail server (MX) records for domain.com"]],tags:"dns"},
{cat:"net",cmd:"dig",desc:"DNS lookup utility (advanced)",detail:"Advanced DNS query tool. More detailed than nslookup. +short for concise output, @server for specific DNS server.",ex:[["dig example.com","Query DNS for example.com (full output)"],["dig +short MX domain.com","Get only mail server addresses (short format)"],["dig @8.8.8.8 example.com","Query DNS using Google's 8.8.8.8 server"]],tags:"dns"},
{cat:"net",cmd:"host",desc:"DNS lookup simple",detail:"Simple DNS lookup tool. Resolves hostnames to IPs and vice versa. -t for record type.",ex:[["host google.com","Resolve google.com to IP address"],["host -t MX gmail.com","Look up MX (mail exchange) records for gmail.com"]],tags:"dns"},
{cat:"net",cmd:"nmap",desc:"Network scanner / port scanner",detail:"Scans networks for hosts, open ports, services, and OS. -sS SYN scan, -O OS detection, -p port range. Essential security tool.",ex:[["nmap 192.168.1.0/24","Scan entire subnet for live hosts"],["nmap -sS -O target.com","SYN scan with OS detection on target.com"],["nmap -p 80,443 host.com","Scan only ports 80 and 443 on host.com"]],tags:"scan,security"},
{cat:"net",cmd:"tcpdump",desc:"Dump network traffic",detail:"Captures and analyzes network packets. -i interface, port filter, -w write to file. Essential for network debugging.",ex:[["tcpdump -i eth0","Capture all traffic on interface eth0"],["tcpdump -i eth0 port 80","Capture only HTTP (port 80) traffic"],["tcpdump -nn -w capture.pcap","Capture to file, no DNS resolution, numeric ports"]],tags:"capture,sniff"},
{cat:"net",cmd:"nc",desc:"Netcat - network utility",detail:"Versatile network tool: port scanner, listener, data transfer, banner grabber. 'Swiss army knife' of networking.",ex:[["nc -l 8080","Listen on port 8080 (simple server)"],["nc host.com 80","Connect to host.com on port 80"],["echo 'test' | nc host 8080","Send 'test' to host on port 8080 then disconnect"]],tags:"netcat,debug"},
{cat:"net",cmd:"whois",desc:"Query WHOIS domain info",detail:"Looks up domain registration info: owner, registrar, nameservers, creation/expiry dates. Also works on IPs.",ex:[["whois example.com","Look up registration info for example.com"],["whois 8.8.8.8","Look up who owns IP address 8.8.8.8"]],tags:"domain,info"},
{cat:"net",cmd:"ftp",desc:"File transfer protocol client",detail:"Transfers files to/from FTP servers. Interactive prompt. -s runs commands from script file.",ex:[["ftp host.com","Connect to FTP server at host.com (interactive)"],["ftp -s:script.txt host.com","Run FTP commands from script.txt automatically"]],tags:"transfer"},
{cat:"net",cmd:"telnet",desc:"Telnet protocol client",detail:"Connects to remote hosts via Telnet (unencrypted). Mainly used for testing ports/connectivity, not secure remote login.",ex:[["telnet host.com 80","Test if port 80 is open on host.com"],["telnet localhost 3306","Test connection to MySQL on local port 3306"]],tags:"connect,debug"},

// ===== Package Management =====
{cat:"pkg",cmd:"apt",desc:"Debian/Ubuntu package manager",detail:"High-level package manager for Debian/Ubuntu. Handles dependencies automatically. update refreshes index, upgrade installs updates, install/remove software.",ex:[["sudo apt update && sudo apt upgrade","Refresh package list then upgrade all packages"],["sudo apt install nginx","Install nginx and its dependencies"],["sudo apt remove --purge nginx","Remove nginx and its config files"],["apt search keyword","Search for packages matching 'keyword'"],["apt list --installed","List all installed packages"]],tags:"debian,ubuntu"},
{cat:"pkg",cmd:"apt-get",desc:"Debian package handling (lower-level)",detail:"Lower-level package tool for Debian/Ubuntu. Less user-friendly than apt but more scriptable. -y auto-confirm.",ex:[["sudo apt-get update","Refresh the package index from repositories"],["sudo apt-get install -y package","Install package, automatically answer yes to prompts"],["sudo apt-get autoremove","Remove unused dependency packages"]],tags:"debian"},
{cat:"pkg",cmd:"dpkg",desc:"Debian package installer (low-level)",detail:"Low-level .deb package manager. -i install, -r remove, -l list, -L list files. Doesn't handle dependencies automatically.",ex:[["dpkg -i package.deb","Install a .deb package file"],["dpkg -r package","Remove an installed package (keep configs)"],["dpkg -l | grep nginx","List installed packages, filter for nginx"],["dpkg -L package","List all files installed by a package"]],tags:"debian,deb"},
{cat:"pkg",cmd:"yum",desc:"RHEL/CentOS package manager",detail:"Package manager for RHEL/CentOS. install, update, remove, search, list. Being replaced by dnf on newer systems.",ex:[["sudo yum install nginx","Install nginx package"],["sudo yum update","Update all installed packages"],["yum search keyword","Search for packages by keyword"],["yum list installed","List all installed packages"]],tags:"rhel,centos"},
{cat:"pkg",cmd:"dnf",desc:"Fedora package manager (modern yum)",detail:"Next-gen replacement for yum on Fedora/RHEL 8+. Faster, better dependency resolution. Same basic commands as yum.",ex:[["sudo dnf install package","Install a package"],["sudo dnf upgrade","Upgrade all packages to latest versions"],["dnf search keyword","Search available packages by keyword"]],tags:"fedora"},
{cat:"pkg",cmd:"rpm",desc:"RPM package manager",detail:"Low-level RPM package tool. -i install, -e erase, -qa list all, -ql list files, -ivh install with progress. No dependency resolution.",ex:[["rpm -ivh package.rpm","Install RPM package with progress and hash marks"],["rpm -e package","Erase (remove) an installed package"],["rpm -qa | grep nginx","List all installed RPMs, filter for nginx"],["rpm -ql package","List all files installed by a package"]],tags:"rpm"},
{cat:"pkg",cmd:"pacman",desc:"Arch Linux package manager",detail:"Package manager for Arch Linux. -Syu sync+update, -S install, -Ss search, -Ql list files. Fast and simple.",ex:[["sudo pacman -Syu","Sync repos and update all packages (full system upgrade)"],["sudo pacman -S package","Install a package"],["pacman -Ss keyword","Search for packages by keyword"],["pacman -Ql package","List files installed by a package"]],tags:"arch"},
{cat:"pkg",cmd:"snap",desc:"Snap package manager",detail:"Universal package manager by Canonical. Packages include all dependencies. Works across Linux distributions.",ex:[["sudo snap install package","Install a snap package"],["sudo snap list","List all installed snap packages"],["sudo snap remove package","Remove an installed snap package"]],tags:"snap,universal"},
{cat:"pkg",cmd:"flatpak",desc:"Flatpak application manager",detail:"Sandboxed application manager for Linux. Apps run in isolation with their own dependencies. flathub is the main repository.",ex:[["flatpak install flathub app.id","Install an app from Flathub repository"],["flatpak list","List all installed Flatpak apps"],["flatpak run app.id","Run an installed Flatpak application"]],tags:"flatpak"},
{cat:"pkg",cmd:"pip",desc:"Python package installer",detail:"Installs Python packages from PyPI. install, -r from requirements file, freeze for reproducible envs, uninstall.",ex:[["pip install package","Install a Python package from PyPI"],["pip install -r requirements.txt","Install all packages listed in requirements.txt"],["pip freeze > requirements.txt","Save current package versions to file"],["pip uninstall package","Remove an installed Python package"]],tags:"python"},
{cat:"pkg",cmd:"npm",desc:"Node.js package manager",detail:"Package manager for Node.js. install, -g global, update, list. Reads package.json for project dependencies.",ex:[["npm install package","Install a package locally in project"],["npm install -g package","Install a package globally (system-wide)"],["npm update","Update all project dependencies"],["npm list -g --depth=0","List globally installed packages (top level only)"]],tags:"nodejs"},
{cat:"pkg",cmd:"gem",desc:"Ruby package manager",detail:"Installs Ruby gems (packages) from rubygems.org. install, list, update. Uses Gemfile with bundler.",ex:[["gem install package","Install a Ruby gem"],["gem list","List all installed gems"],["gem update","Update all installed gems to latest versions"]],tags:"ruby"},
{cat:"pkg",cmd:"cargo",desc:"Rust package manager",detail:"Rust's package manager and build system. new creates project, build compiles, add dependency, run executes. Uses Cargo.toml.",ex:[["cargo new project","Create a new Rust project with scaffold"],["cargo build","Compile the project"],["cargo add crate-name","Add a dependency to Cargo.toml"],["cargo run","Compile and run the project"]],tags:"rust"},

// ===== Compression & Archive =====
{cat:"archive",cmd:"tar",desc:"Archive utility (tarballs)",detail:"Creates or extracts archive files. -c create, -x extract, -z gzip, -j bzip2, -v verbose, -f filename. Most common archive tool.",ex:[["tar -czvf archive.tar.gz dir/","Create gzip-compressed tarball of dir/"],["tar -xzvf archive.tar.gz","Extract a gzip-compressed tarball"],["tar -tf archive.tar.gz","List contents of tarball without extracting"],["tar -cjvf archive.tar.bz2 dir/","Create bzip2-compressed tarball (smaller, slower)"]],tags:"tarball,gzip"},
{cat:"archive",cmd:"gzip",desc:"Compress files (gzip)",detail:"Compresses single files (adds .gz extension). -k keep original, -d decompress, -1 to -9 compression level.",ex:[["gzip file.txt","Compress file.txt (replaces original with .gz)"],["gzip -k file.txt","Compress but keep the original file"],["gzip -d file.gz","Decompress file.gz back to file.txt"]],tags:"compress,gz"},
{cat:"archive",cmd:"gunzip",desc:"Decompress gzip files",detail:"Decompresses .gz files back to original. -c outputs to stdout instead of replacing file. Same as 'gzip -d'.",ex:[["gunzip file.gz","Decompress file.gz to file.txt"],["gunzip -c file.gz > output.txt","Decompress to stdout, save to output.txt"]],tags:"decompress"},
{cat:"archive",cmd:"zip",desc:"Package and compress files",detail:"Creates ZIP archives. -r recursive, -e encrypt with password, -9 maximum compression. Cross-platform format.",ex:[["zip -r archive.zip dir/","Recursively zip entire directory into archive.zip"],["zip -e secret.zip file.txt","Create password-encrypted zip file"],["zip -9 max.zip *.txt","Create zip with maximum compression level"]],tags:"compress"},
{cat:"archive",cmd:"unzip",desc:"Extract ZIP files",detail:"Extracts ZIP archives. -d target directory, -l list contents without extracting, -o overwrite without prompt.",ex:[["unzip archive.zip","Extract archive.zip into current directory"],["unzip -d /target archive.zip","Extract into /target directory"],["unzip -l archive.zip","List contents of zip without extracting"]],tags:"extract"},
{cat:"archive",cmd:"bzip2",desc:"Block-sorting file compressor",detail:"Compresses files with higher ratio than gzip but slower. -k keep original, -d decompress. Creates .bz2 files.",ex:[["bzip2 file.txt","Compress file.txt to .bz2 (replaces original)"],["bzip2 -d file.bz2","Decompress .bz2 file back to original"],["bzip2 -k file.txt","Compress but keep the original file"]],tags:"compress,bz2"},
{cat:"archive",cmd:"xz",desc:"General-purpose data compression",detail:"High-ratio compression tool. Better compression than gzip/bzip2 but slower. -d decompress, -k keep, -9 max.",ex:[["xz file.txt","Compress file.txt to .xz (replaces original)"],["xz -d file.xz","Decompress .xz file back to original"],["xz -k -9 file.txt","Compress with maximum ratio, keep original"]],tags:"compress,xz"},
{cat:"archive",cmd:"7z",desc:"7-Zip archiver",detail:"High-ratio archiver supporting many formats. a add/create, x extract, l list. Strong AES-256 encryption.",ex:[["7z a archive.7z dir/","Add directory to new 7z archive"],["7z x archive.7z","Extract 7z archive with full paths"],["7z l archive.7z","List contents of 7z archive"]],tags:"compress,7zip"},
{cat:"archive",cmd:"zcat",desc:"View compressed files",detail:"Displays contents of gzip-compressed files without decompressing to disk. Same as 'gunzip -c'.",ex:[["zcat file.gz","Display contents of compressed file without extracting"],["zcat access.log.gz | grep 'error'","Search compressed log for 'error' without extracting"]],tags:"view,compressed"},
{cat:"archive",cmd:"zgrep",desc:"Search inside compressed files",detail:"Searches text inside gzip-compressed files without extracting. Same syntax as grep. Useful for searching compressed logs.",ex:[["zgrep 'error' log.gz","Search for 'error' inside compressed log file"],["zgrep -i 'warning' *.gz","Case-insensitive search across all compressed files"]],tags:"search,compressed"},

// ===== System Information =====
{cat:"system",cmd:"uname",desc:"Print system information",detail:"Shows system info: kernel name, version, architecture. -a all info, -r kernel release, -m machine arch.",ex:[["uname -a","Show all system info (kernel, hostname, arch, etc.)"],["uname -r","Show kernel release version only"],["uname -m","Show machine hardware architecture (e.g. x86_64)"]],tags:"kernel,info"},
{cat:"system",cmd:"hostname",desc:"Show or set system hostname",detail:"Displays or sets the system's network name. -I shows IP addresses, hostnamectl for persistent changes.",ex:[["hostname","Show the system's hostname"],["hostname -I","Show all IP addresses of this machine"],["hostnamectl set-hostname newname","Permanently change hostname to 'newname'"]],tags:"hostname"},
{cat:"system",cmd:"uptime",desc:"Show system uptime and load",detail:"Shows how long system has been running, number of users, and load averages (1/5/15 min). -p pretty format.",ex:[["uptime","Show uptime, users, and load averages"],["uptime -p","Show uptime in human-readable format (e.g. 'up 3 days')"]],tags:"uptime,load"},
{cat:"system",cmd:"free",desc:"Display memory usage",detail:"Shows total/used/free RAM and swap. -h human-readable, -m in MB, -s N refresh every N seconds.",ex:[["free -h","Show memory usage in human-readable units (MB/GB)"],["free -m","Show memory usage in megabytes"],["free -s 5","Continuously update memory display every 5 seconds"]],tags:"memory,ram"},
{cat:"system",cmd:"lscpu",desc:"Display CPU information",detail:"Shows CPU architecture details: cores, threads, cache, model, frequency. Useful for hardware inventory.",ex:[["lscpu","Display detailed CPU architecture information"],["lscpu | grep 'Model name'","Show just the CPU model name"]],tags:"cpu"},
{cat:"system",cmd:"lsblk",desc:"List block devices",detail:"Lists disk partitions and their mount points in tree format. -f shows filesystem types, -o custom columns.",ex:[["lsblk","List all block devices (disks, partitions) in tree view"],["lsblk -f","Show filesystem type and UUID for each device"],["lsblk -o NAME,SIZE,TYPE,MOUNTPOINT","Show specific columns only"]],tags:"disk,block"},
{cat:"system",cmd:"lspci",desc:"List PCI devices",detail:"Lists all PCI devices (graphics cards, network adapters, USB controllers). -v verbose, grep to filter.",ex:[["lspci","List all PCI devices in the system"],["lspci -v","Show detailed info for each PCI device"],["lspci | grep -i vga","Find graphics/video cards only"]],tags:"hardware,pci"},
{cat:"system",cmd:"lsusb",desc:"List USB devices",detail:"Lists connected USB devices. -v for detailed info. Useful for diagnosing USB device issues.",ex:[["lsusb","List all connected USB devices"],["lsusb -v","Show detailed info for each USB device"]],tags:"hardware,usb"},
{cat:"system",cmd:"dmidecode",desc:"DMI (SMBIOS) table decoder",detail:"Reads hardware info from BIOS: motherboard, memory, CPU, serial numbers. -t filters by type. Requires root.",ex:[["sudo dmidecode -t memory","Show detailed RAM/memory hardware info"],["sudo dmidecode -t system","Show system/motherboard information"],["sudo dmidecode -t bios","Show BIOS version and details"]],tags:"hardware,info"},
{cat:"system",cmd:"hwinfo",desc:"Hardware information",detail:"Comprehensive hardware detection tool. --short for summary, --cpu, --network for specific categories.",ex:[["hwinfo --short","Show brief summary of all hardware"],["hwinfo --cpu","Show detailed CPU information"],["hwinfo --network","Show network adapter details"]],tags:"hardware"},
{cat:"system",cmd:"lsof",desc:"List open files",detail:"Shows which processes have which files/ports open. -i for network, -u for user, -p for PID. Essential for debugging.",ex:[["lsof -i :80","Show what process is using port 80"],["lsof -u username","Show all files opened by username"],["lsof /var/log/syslog","Show what process has syslog open"],["lsof -p 1234","Show all files opened by process 1234"]],tags:"files,open"},
{cat:"system",cmd:"dmesg",desc:"Print kernel ring buffer",detail:"Shows kernel messages: boot info, hardware detection, driver errors. Useful for troubleshooting hardware/driver issues.",ex:[["dmesg","Show all kernel ring buffer messages"],["dmesg | tail -50","Show the last 50 kernel messages"],["dmesg --level=err,warn","Show only error and warning messages"]],tags:"kernel,log"},
{cat:"system",cmd:"journalctl",desc:"Query systemd journal",detail:"Queries systemd's centralized logging. -u for service, --since for time, -f follow, -p for priority. Replaces /var/log on systemd systems.",ex:[["journalctl -u nginx","Show logs for nginx service"],["journalctl --since today","Show all logs since today"],["journalctl -f","Follow logs in real-time (like tail -f)"],["journalctl -p err","Show only error-level and above messages"]],tags:"log,systemd"},
{cat:"system",cmd:"systemctl",desc:"Control systemd services",detail:"Manages systemd services. start/stop/restart, enable/disable autostart, status check, reload config.",ex:[["sudo systemctl start nginx","Start the nginx service now"],["sudo systemctl enable nginx","Make nginx start automatically on boot"],["systemctl status nginx","Check if nginx is running and its status"],["systemctl restart nginx","Restart nginx (stop then start)"]],tags:"service,systemd"},
{cat:"system",cmd:"service",desc:"Run a system service (init.d)",detail:"Legacy service manager (SysV init). start/stop/restart/status. Replaced by systemctl on modern systems.",ex:[["sudo service nginx start","Start nginx using legacy init.d system"],["sudo service nginx status","Check nginx service status"],["service --status-all","List status of all services"]],tags:"service"},
{cat:"system",cmd:"date",desc:"Display or set date/time",detail:"Shows or sets system date/time. Supports custom format strings (+%Y-%m-%d). -u for UTC, -s to set.",ex:[["date","Show current date and time"],["date '+%Y-%m-%d %H:%M:%S'","Show date in custom format: 2026-07-25 10:30:00"],["date -u","Show current UTC time"],["sudo date -s '2026-07-25 10:00:00'","Set system date and time manually"]],tags:"time,date"},
{cat:"system",cmd:"timedatectl",desc:"Control system time and date",detail:"Manages system time, timezone, and NTP sync. set-timezone changes zone, set-ntp enables automatic sync.",ex:[["timedatectl","Show current time, timezone, and NTP status"],["timedatectl set-timezone Asia/Shanghai","Set system timezone to Asia/Shanghai"],["timedatectl set-ntp true","Enable automatic time sync via NTP"]],tags:"timezone"},
{cat:"system",cmd:"cal",desc:"Display a calendar",detail:"Shows a monthly calendar. -3 shows 3 months, -y full year, or specify year/month as argument.",ex:[["cal","Show calendar for current month"],["cal -3","Show previous, current, and next month"],["cal 2026","Show full calendar for year 2026"],["cal -y","Show calendar for the entire current year"]],tags:"calendar"},
{cat:"system",cmd:"who",desc:"Show who is logged in",detail:"Lists logged-in users with terminal, login time, and source IP. -b boot time, -q user count.",ex:[["who","List all currently logged-in users"],["who -b","Show when the system was last booted"],["who -q","Show count of logged-in users"]],tags:"users,login"},
{cat:"system",cmd:"w",desc:"Show who is logged in and what they do",detail:"Enhanced who: shows logged-in users AND their current process/CPU usage. More detailed than who.",ex:[["w","Show all logged-in users and their activity"],["w username","Show activity for a specific user"]],tags:"users,activity"},
{cat:"system",cmd:"last",desc:"Show last logged in users",detail:"Shows login history from /var/log/wtmp. -10 limits to 10, -x includes shutdown/reboot entries.",ex:[["last","Show recent login history for all users"],["last -10","Show the last 10 login sessions"],["last -x reboot","Show system reboot history"]],tags:"login,history"},
{cat:"system",cmd:"history",desc:"Show command history",detail:"Lists previously executed commands. !N reruns command N, !! reruns last, !string reruns last matching. -c clears.",ex:[["history","Show all commands in history"],["history | grep ssh","Find ssh commands in history"],["!123","Re-run command number 123 from history"],["history -c","Clear the entire command history"]],tags:"history"},

// ===== Disk & Storage =====
{cat:"disk",cmd:"fdisk",desc:"Manipulate disk partition table",detail:"Views or modifies disk partition tables. -l lists all partitions. Interactive mode for creating/deleting partitions. MBR/GPT.",ex:[["sudo fdisk -l","List all disk partitions on all drives"],["sudo fdisk /dev/sda","Open interactive partition editor for /dev/sda"]],tags:"partition"},
{cat:"disk",cmd:"parted",desc:"Partition editor",detail:"Advanced partition editor supporting GPT and MBR. -l lists, interactive mode. More capable than fdisk for large disks.",ex:[["sudo parted -l","List all partitions on all disks"],["sudo parted /dev/sda","Open interactive partition editor for /dev/sda"]],tags:"partition"},
{cat:"disk",cmd:"mkfs",desc:"Create a filesystem",detail:"Formats a partition with a filesystem. ext4 for Linux, ntfs for Windows, xfs for large storage. Destroys existing data!",ex:[["sudo mkfs.ext4 /dev/sda1","Format partition as ext4 (standard Linux filesystem)"],["sudo mkfs.ntfs -f /dev/sdb1","Format as NTFS (Windows-compatible, fast mode)"],["sudo mkfs.xfs /dev/sdc1","Format as XFS (good for large files/storage)"]],tags:"format,filesystem"},
{cat:"disk",cmd:"mount",desc:"Mount a filesystem",detail:"Attaches a filesystem/device to the directory tree. -t type, -o options. Listed in /etc/fstab for auto-mount at boot.",ex:[["sudo mount /dev/sda1 /mnt","Mount partition sda1 to /mnt directory"],["sudo mount -t nfs host:/share /mnt","Mount NFS network share to /mnt"],["mount | column -t","List all mounted filesystems in readable format"]],tags:"mount"},
{cat:"disk",cmd:"umount",desc:"Unmount a filesystem",detail:"Detaches a mounted filesystem. -l lazy unmount (force). Always unmount before removing media to prevent data loss.",ex:[["sudo umount /mnt","Unmount the filesystem at /mnt"],["sudo umount -l /mnt","Lazy unmount (detach now, clean up later)"]],tags:"unmount"},
{cat:"disk",cmd:"fsck",desc:"Check and repair filesystem",detail:"Filesystem check and repair tool. -y auto-fix. Run on unmounted filesystems. Fixes corruption from crashes/power loss.",ex:[["sudo fsck /dev/sda1","Check filesystem on sda1 for errors"],["sudo fsck -y /dev/sda1","Check and automatically repair all errors"]],tags:"check,repair"},
{cat:"disk",cmd:"dd",desc:"Convert and copy files (low-level)",detail:"Low-level block copy tool. Clones disks, creates disk images, writes ISOs to USB. VERY dangerous if used wrong. bs=block size.",ex:[["sudo dd if=/dev/sda of=disk.img bs=4M","Create a disk image of /dev/sda"],["sudo dd if=iso of=/dev/sdb bs=4M status=progress","Write ISO image to USB drive /dev/sdb with progress"]],tags:"clone,image"},
{cat:"disk",cmd:"blkid",desc:"Locate/print block device attributes",detail:"Shows UUID and filesystem type of block devices. UUIDs are used in /etc/fstab for reliable mounting.",ex:[["blkid","Show UUID and type for all block devices"],["blkid /dev/sda1","Show attributes for specific partition sda1"]],tags:"uuid,block"},
{cat:"disk",cmd:"smartctl",desc:"SMART disk health monitoring",detail:"Reads SMART health data from disks. -a all info, -t runs test. Predicts disk failure before it happens.",ex:[["sudo smartctl -a /dev/sda","Show all SMART health data for /dev/sda"],["sudo smartctl -t short /dev/sda","Run a short SMART self-test on /dev/sda"]],tags:"health,disk"},
{cat:"disk",cmd:"iostat",desc:"I/O statistics",detail:"Reports CPU and disk I/O statistics. -x extended, -d disk only, interval for refresh. Useful for I/O bottleneck diagnosis.",ex:[["iostat","Show basic CPU and disk I/O statistics"],["iostat -x 2","Show extended I/O stats, refresh every 2 seconds"],["iostat -d sda","Show stats for disk sda only"]],tags:"io,stats"},
{cat:"disk",cmd:"ncdu",desc:"NCurses disk usage analyzer",detail:"Interactive disk usage viewer with ncurses interface. Navigate and find large files/dirs easily. -x one filesystem.",ex:[["ncdu /","Interactive disk usage analyzer starting from root"],["ncdu /var","Analyze disk usage of /var directory"],["ncdu -x /","Analyze only root filesystem (don't cross mount points)"]],tags:"disk,analyze"},

// ===== User & Group =====
{cat:"user",cmd:"useradd",desc:"Create a new user",detail:"Creates user accounts. -m creates home dir, -s sets shell, -G adds to groups. Lower-level than adduser.",ex:[["sudo useradd -m -s /bin/bash username","Create user with home dir and bash shell"],["sudo useradd -m -G sudo,docker username","Create user and add to sudo and docker groups"]],tags:"create,user"},
{cat:"user",cmd:"usermod",desc:"Modify a user account",detail:"Modifies existing users. -aG append to group, -L lock, -U unlock, -s change shell, -l rename.",ex:[["sudo usermod -aG docker username","Add user to docker group (append, don't replace)"],["sudo usermod -L username","Lock user account (prevent login)"],["sudo usermod -s /bin/zsh username","Change user's default shell to zsh"]],tags:"modify,user"},
{cat:"user",cmd:"userdel",desc:"Delete a user account",detail:"Removes user accounts. -r also removes home directory and mail spool. Use carefully—data is permanent.",ex:[["sudo userdel username","Delete user account (keep home directory)"],["sudo userdel -r username","Delete user AND remove their home directory"]],tags:"delete,user"},
{cat:"user",cmd:"passwd",desc:"Change user password",detail:"Sets or changes user passwords. Run without args for own password. -l lock, -u unlock, -d delete password.",ex:[["passwd","Change your own password"],["sudo passwd username","Set password for another user"],["passwd -l username","Lock account by disabling password"]],tags:"password"},
{cat:"user",cmd:"groupadd",desc:"Create a new group",detail:"Creates group accounts. -g sets specific GID. Groups are used for permission management.",ex:[["sudo groupadd developers","Create a group called 'developers'"],["sudo groupadd -g 2000 team","Create group 'team' with specific GID 2000"]],tags:"group,create"},
{cat:"user",cmd:"groupdel",desc:"Delete a group",detail:"Removes a group. Cannot delete if it's any user's primary group. Files keep the GID numerically.",ex:[["sudo groupdel developers","Delete the 'developers' group"]],tags:"group,delete"},
{cat:"user",cmd:"gpasswd",desc:"Administer /etc/group",detail:"Manages group membership. -a add user to group, -d remove user, -A set group administrators.",ex:[["sudo gpasswd -a username docker","Add username to the docker group"],["sudo gpasswd -d username docker","Remove username from the docker group"]],tags:"group,member"},
{cat:"user",cmd:"id",desc:"Print user and group IDs",detail:"Shows UID, GID, and all group memberships for a user. Useful for permission troubleshooting.",ex:[["id","Show your own UID, GID, and groups"],["id username","Show identity info for a specific user"],["id -Gn username","Show only group names for username"]],tags:"identity"},
{cat:"user",cmd:"groups",desc:"Show group memberships",detail:"Lists groups a user belongs to. Simpler than 'id' for just group names.",ex:[["groups","Show groups you belong to"],["groups username","Show groups for a specific user"]],tags:"group"},
{cat:"user",cmd:"whoami",desc:"Print current user name",detail:"Shows the current effective username. Useful in scripts to check who's running.",ex:[["whoami","Print the username of the current user"]],tags:"identity"},

// ===== Text Editors =====
{cat:"editor",cmd:"vim",desc:"Vi IMproved text editor",detail:"Powerful modal text editor. Normal mode for navigation/commands, Insert mode for editing. :wq save & quit, :q! force quit.",ex:[["vim file.txt","Open file.txt in vim editor"],["vim +42 file.txt","Open file.txt and jump to line 42"],[":q!","Quit without saving changes"],[":wq","Save changes and quit"]],tags:"editor,vi"},
{cat:"editor",cmd:"nano",desc:"Simple text editor",detail:"Beginner-friendly text editor with on-screen shortcuts. Ctrl+O save, Ctrl+X exit, Ctrl+W search. No modal modes.",ex:[["nano file.txt","Open file.txt in nano editor"],["nano -l file.txt","Open with line numbers displayed"],["Ctrl+O then Enter","Save file (write out)"],["Ctrl+X","Exit nano"]],tags:"editor,simple"},
{cat:"editor",cmd:"vi",desc:"Standard vi editor",detail:"Original vi editor. Modal editing like vim but fewer features. Available on all Unix systems as baseline editor.",ex:[["vi file.txt","Open file.txt in vi editor"],[":wq","Save changes and quit"],[":q!","Force quit without saving"]],tags:"editor"},
{cat:"editor",cmd:"emacs",desc:"GNU Emacs editor",detail:"Extensible text editor and environment. -nw runs in terminal without GUI. Highly customizable with Emacs Lisp.",ex:[["emacs file.txt","Open file.txt in emacs GUI"],["emacs -nw file.txt","Open in terminal mode (no window/GUI)"]],tags:"editor"},

// ===== Shell & Scripting =====
{cat:"shell",cmd:"echo",desc:"Display a line of text",detail:"Outputs text to stdout. -e enables escape sequences (\\n, \\t), -n suppresses trailing newline. Also shows variable values.",ex:[["echo 'Hello World'","Print Hello World to screen"],["echo -e 'Line1\\nLine2'","Print two lines using newline escape sequence"],["echo $PATH","Display the PATH environment variable"],["echo {1..10}","Print numbers 1 through 10 (brace expansion)"]],tags:"print"},
{cat:"shell",cmd:"printf",desc:"Format and print data",detail:"C-style formatted output. More control than echo: %s strings, %d integers, %f floats, width/alignment specifiers.",ex:[["printf '%s\\n' 'Hello'","Print 'Hello' with a newline (like echo)"],["printf '%-10s %5d\\n' 'Name' 42","Print left-aligned string (10 wide) and right-aligned number (5 wide)"]],tags:"format,print"},
{cat:"shell",cmd:"export",desc:"Set environment variables",detail:"Sets environment variables available to child processes. Without assignment, -p lists all exported vars. Common in .bashrc.",ex:[["export PATH=$PATH:/new/bin","Add /new/bin to PATH environment variable"],["export MY_VAR='value'","Set a custom environment variable"],["export -p","List all currently exported environment variables"]],tags:"env,variable"},
{cat:"shell",cmd:"alias",desc:"Create command aliases",detail:"Creates shortcuts for commands. Persist in .bashrc/.zshrc. Without args, lists all current aliases.",ex:[["alias ll='ls -lah'","Create shortcut 'll' for 'ls -lah'"],["alias ..='cd ..'","Create shortcut '..' for 'cd ..'"],["alias","List all currently defined aliases"]],tags:"shortcut"},
{cat:"shell",cmd:"source",desc:"Execute commands from a file",detail:"Runs commands from a file in the current shell (not subshell). Reloads configs after editing. Also written as '.'.",ex:[["source ~/.bashrc","Reload bashrc to apply changes"],["source venv/bin/activate","Activate a Python virtual environment"],[". script.sh","Run script.sh in current shell (shorthand)"]],tags:"execute,import"},
{cat:"shell",cmd:"env",desc:"Run command in modified environment",detail:"Shows or modifies environment variables for command execution. -i starts with empty environment. Without command, lists all vars.",ex:[["env","List all environment variables"],["env VAR=value command","Run command with a custom env variable"],["env -i command","Run command with empty environment (no vars)"]],tags:"environment"},
{cat:"shell",cmd:"set",desc:"Set shell options and positional params",detail:"Configures shell behavior. -e exit on error, -x debug trace, -o pipefail. Essential for robust scripts.",ex:[["set -e","Exit script immediately if any command fails"],["set -x","Print each command before executing (debug mode)"],["set -o pipefail","A pipeline fails if any command fails (not just the last)"]],tags:"shell,options"},
{cat:"shell",cmd:"unset",desc:"Remove variables or functions",detail:"Deletes shell variables or functions. -f for functions only. Variables become unset for current and child shells.",ex:[["unset MY_VAR","Remove the MY_VAR environment variable"],["unset -f my_function","Remove a shell function"]],tags:"variable"},
{cat:"shell",cmd:"read",desc:"Read a line from input",detail:"Reads user input into variables. -p prompt, -s silent (passwords), -a array, -t timeout. Essential for interactive scripts.",ex:[["read -p 'Name: ' name","Prompt 'Name:' and read input into variable 'name'"],["read -s -p 'Password: ' pass","Read password silently (no echo)"],["read -a arr <<< 'a b c'","Read space-separated values into array"]],tags:"input"},
{cat:"shell",cmd:"test",desc:"Evaluate conditions ([ ])",detail:"Tests file types, string equality, numeric comparison. Returns 0 (true) or 1 (false). [ ] is shorthand. -f file, -d dir, = equal.",ex:[["test -f file.txt && echo exists","If file.txt exists, print 'exists'"],["[ -d /var ] && echo dir","If /var is a directory, print 'dir'"],["[ \"$a\" = \"$b\" ]","Test if variables a and b are equal"]],tags:"condition"},
{cat:"shell",cmd:"expr",desc:"Evaluate expressions",detail:"Evaluates arithmetic, string, and logical expressions. Legacy tool—use $(( )) for arithmetic in modern shells.",ex:[["expr 5 + 3","Calculate 5 + 3 = 8"],["expr length 'hello'","Get length of string 'hello' = 5"],["expr substr 'hello' 1 3","Extract substring: chars 1-3 = 'hel'"]],tags:"math,evaluate"},
{cat:"shell",cmd:"bc",desc:"Arbitrary precision calculator",detail:"Command-line calculator supporting decimals, math functions, variables. scale sets decimal precision. Reads from stdin.",ex:[["echo '5+3' | bc","Calculate 5+3 = 8"],["echo 'scale=2; 10/3' | bc","Divide 10/3 with 2 decimal places = 3.33"],["echo '2^10' | bc","Calculate 2 to the power of 10 = 1024"]],tags:"calculator"},
{cat:"shell",cmd:"cron",desc:"Schedule periodic tasks",detail:"Schedules recurring tasks (cron jobs). Edit with crontab -e. Format: minute hour day month weekday command. Runs automatically.",ex:[["crontab -e","Edit your cron jobs in editor"],["crontab -l","List all your scheduled cron jobs"],["0 2 * * * /backup.sh","Run /backup.sh every day at 2:00 AM"]],tags:"schedule"},
{cat:"shell",cmd:"at",desc:"Schedule one-time tasks",detail:"Schedules a command to run once at a specified time. Unlike cron, it's one-shot. 'at now + 1 hour' for relative time.",ex:[["echo 'backup.sh' | at 2am","Run backup.sh once at 2 AM today"],["echo 'reboot' | at now + 1 hour","Run reboot command one hour from now"]],tags:"schedule,once"},

// ===== Firewall & Security =====
{cat:"security",cmd:"iptables",desc:"Configure IPv4 packet filtering",detail:"Linux kernel firewall configuration. Sets rules for packet filtering/NAT. -L list, -A append, -F flush. Complex but powerful.",ex:[["sudo iptables -L","List all current firewall rules"],["sudo iptables -A INPUT -p tcp --dport 80 -j ACCEPT","Allow incoming TCP traffic on port 80"],["sudo iptables -F","Flush (delete) all firewall rules"]],tags:"firewall"},
{cat:"security",cmd:"ufw",desc:"Uncomplicated Firewall (Ubuntu)",detail:"Simplified firewall frontend for iptables on Ubuntu. allow/deny ports, enable/disable. Much easier than raw iptables.",ex:[["sudo ufw allow 80/tcp","Allow incoming TCP connections on port 80"],["sudo ufw enable","Enable the firewall"],["sudo ufw status verbose","Show detailed firewall status and rules"]],tags:"firewall,ubuntu"},
{cat:"security",cmd:"firewalld",desc:"Dynamic firewall manager",detail:"Firewall management for RHEL/CentOS/Fedora. Uses zones and services. --add-port, --reload, --list-all. No restart needed for changes.",ex:[["sudo firewall-cmd --list-all","Show all firewall zones and rules"],["sudo firewall-cmd --add-port=80/tcp --permanent","Permanently allow port 80 TCP"],["sudo firewall-cmd --reload","Reload firewall to apply permanent changes"]],tags:"firewall"},
{cat:"security",cmd:"openssl",desc:"OpenSSL cryptography toolkit",detail:"SSL/TLS toolkit: generate keys, create CSRs, sign certificates, test connections. Essential for HTTPS setup.",ex:[["openssl genrsa -out key.pem 2048","Generate a 2048-bit RSA private key"],["openssl req -new -x509 -key key.pem -out cert.pem","Create a self-signed certificate using the key"],["openssl s_client -connect host:443","Test SSL connection to a host on port 443"]],tags:"ssl,crypto"},
{cat:"security",cmd:"gpg",desc:"GNU Privacy Guard encryption",detail:"Encrypts/signs files and emails using public-key cryptography. --encrypt, --decrypt, --gen-key. OpenPGP standard.",ex:[["gpg --encrypt file.txt","Encrypt file.txt using public key"],["gpg --decrypt file.gpg","Decrypt an encrypted .gpg file"],["gpg --gen-key","Generate a new GPG key pair"]],tags:"encrypt,pgp"},
{cat:"security",cmd:"ssh-keygen",desc:"Generate SSH key pairs",detail:"Creates SSH key pairs for passwordless authentication. -t key type (ed25519 recommended), -C comment, -f output file.",ex:[["ssh-keygen -t ed25519 -C 'email'","Generate ed25519 key (recommended, modern)"],["ssh-keygen -t rsa -b 4096","Generate 4096-bit RSA key (compatible)"],["ssh-keygen -f ~/.ssh/id_rsa","Generate key to specific file path"]],tags:"ssh,key"},
{cat:"security",cmd:"fail2ban",desc:"Ban IPs with too many failures",detail:"Automatically bans IPs after repeated failed login attempts (SSH, web). Protects against brute-force attacks.",ex:[["sudo fail2ban-client status","Show status of all fail2ban jails"],["sudo fail2ban-client status sshd","Show banned IPs for SSH jail"],["sudo fail2ban-client set sshd unbanip IP","Unban a specific IP address from SSH jail"]],tags:"ban,security"},

// ===== Performance & Monitoring =====
{cat:"monitor",cmd:"vmstat",desc:"Virtual memory statistics",detail:"Reports virtual memory, processes, CPU, I/O stats. Interval for continuous refresh. -s summary statistics.",ex:[["vmstat","Show one-time snapshot of memory and CPU stats"],["vmstat 2 5","Update stats every 2 seconds, 5 times total"],["vmstat -s","Show statistics in a table/summary format"]],tags:"memory,stats"},
{cat:"monitor",cmd:"mpstat",desc:"Processor statistics",detail:"Reports per-CPU usage statistics. -P ALL for all cores, interval for refresh. Useful for multi-core monitoring.",ex:[["mpstat","Show CPU statistics for all processors"],["mpstat -P ALL 2","Show per-core stats, refresh every 2 seconds"],["mpstat 1 5","Show CPU stats every 1 second, 5 times"]],tags:"cpu,stats"},
{cat:"monitor",cmd:"sar",desc:"System activity reporter",detail:"Collects and reports system activity: CPU, memory, disk, network. Historical data if sysstat package installed.",ex:[["sar -u 1 5","Show CPU usage, refresh every 1s, 5 times"],["sar -r","Show memory usage statistics"],["sar -n DEV","Show network device statistics"]],tags:"performance"},
{cat:"monitor",cmd:"iotop",desc:"I/O monitoring (top for disk)",detail:"Shows which processes are using disk I/O in real-time. -o only shows active I/O processes. Requires root.",ex:[["sudo iotop","Show real-time disk I/O usage by process"],["sudo iotop -o","Show only processes doing I/O right now"]],tags:"io,disk"},
{cat:"monitor",cmd:"iftop",desc:"Network bandwidth monitor",detail:"Shows real-time network bandwidth usage by connection. -i interface, -n no DNS. Like top for network traffic.",ex:[["sudo iftop","Show real-time network bandwidth usage"],["sudo iftop -i eth0","Monitor traffic on specific interface eth0"],["sudo iftop -n","Show IP addresses without DNS resolution"]],tags:"network,bandwidth"},
{cat:"monitor",cmd:"nethogs",desc:"Per-process network usage",detail:"Shows network bandwidth per process (not per connection). Identifies which app is using network. Requires root.",ex:[["sudo nethogs","Show network usage per process"],["sudo nethogs eth0","Monitor specific interface eth0"]],tags:"network,per-process"},
{cat:"monitor",cmd:"glances",desc:"System monitoring (all-in-one)",detail:"Comprehensive system monitor: CPU, memory, disk, network, processes, temps. -w web mode, -t refresh interval.",ex:[["glances","Open comprehensive system monitor"],["glances -w","Open monitor in web browser mode"],["glances -t 2","Refresh every 2 seconds"]],tags:"monitor,all"},
{cat:"monitor",cmd:"strace",desc:"Trace system calls",detail:"Traces system calls made by a process. -p attach to PID, -c summary, -e filter. Essential for debugging.",ex:[["strace ls /tmp","Trace all system calls when running 'ls /tmp'"],["strace -p 1234","Attach to running process 1234 and trace calls"],["strace -c command","Show summary count of system calls"]],tags:"trace,debug"},
{cat:"monitor",cmd:"ltrace",desc:"Trace library calls",detail:"Traces dynamic library calls made by a process. Similar to strace but for library functions. -p attach to PID.",ex:[["ltrace ./program","Trace library calls made by program"],["ltrace -p 1234","Attach to running process 1234 and trace library calls"]],tags:"trace,library"},
{cat:"monitor",cmd:"perf",desc:"Linux profiling tools",detail:"Powerful performance profiling tool. top for live view, record/report for profiling, stat for counters. Requires root.",ex:[["sudo perf top","Show live system-wide performance profile"],["sudo perf record command","Record performance data while running command"],["sudo perf report","Analyze recorded performance data"]],tags:"profile"},
{cat:"monitor",cmd:"nload",desc:"Network traffic visualizer",detail:"Simple real-time network traffic graph in terminal. Shows upload/download speed per interface.",ex:[["nload","Show real-time traffic graph for all interfaces"],["nload eth0","Show traffic graph for specific interface eth0"]],tags:"network,visual"},

// ===== Misc / Utilities =====
{cat:"misc",cmd:"man",desc:"Display manual pages",detail:"Shows detailed manual pages for commands. -k searches by keyword, section numbers for specific topics (5=configs). Essential reference.",ex:[["man ls","Show the manual page for ls command"],["man 5 crontab","Show crontab file format documentation (section 5)"],["man -k keyword","Search man pages by keyword (like apropos)"]],tags:"help,manual"},
{cat:"misc",cmd:"tldr",desc:"Simplified man pages with examples",detail:"Community-maintained simplified command reference with practical examples. Much easier than man pages.",ex:[["tldr tar","Show simplified tar examples"],["tldr grep","Show simplified grep examples"],["tldr find","Show simplified find examples"]],tags:"help,simple"},
{cat:"misc",cmd:"which",desc:"Locate a command",detail:"Shows the full path of an executable that would run. Searches PATH. Useful to check which version of a command runs.",ex:[["which python3","Show the full path of python3 executable"],["which nginx","Show where nginx binary is located"]],tags:"locate,path"},
{cat:"misc",cmd:"whereis",desc:"Locate binary, source, man page",detail:"Finds binary, source code, and man page locations for a command. More comprehensive than which.",ex:[["whereis python","Find binary, source, and man page for python"],["whereis nginx","Find all nginx-related file locations"]],tags:"locate"},
{cat:"misc",cmd:"type",desc:"Display command type",detail:"Shows how a command name would be interpreted: alias, builtin, function, or file path. Reveals if something is aliased.",ex:[["type ls","Show what 'ls' actually is (alias, builtin, or file)"],["type cd","Show that cd is a shell builtin"],["type ll","Show if ll is an alias and what it expands to"]],tags:"info"},
{cat:"misc",cmd:"clear",desc:"Clear terminal screen",detail:"Clears the terminal display. Shortcut Ctrl+L does the same. Doesn't affect history or processes.",ex:[["clear","Clear the terminal screen"],["Ctrl+L","Keyboard shortcut to clear screen"]],tags:"terminal"},
{cat:"misc",cmd:"reset",desc:"Reset terminal to default",detail:"Fully resets terminal state when it becomes garbled (after binary output etc). More thorough than clear.",ex:[["reset","Reset terminal to default state (fixes garbled display)"]],tags:"terminal"},
{cat:"misc",cmd:"cowsay",desc:"ASCII cow speaks text",detail:"Fun command: ASCII cow displays a speech bubble with your text. -f changes animal. Often combined with fortune.",ex:[["cowsay 'Hello!'","ASCII cow says Hello"],["cowthink 'Hmm...'","ASCII cow thinks (thought bubble)"],["cowsay -f tux 'Linux!'","Use Tux (Linux penguin) instead of cow"]],tags:"fun"},
{cat:"misc",cmd:"figlet",desc:"ASCII art text banners",detail:"Creates large ASCII art text from input. Various fonts available. Popular for terminal greetings/motd.",ex:[["figlet Hello","Print 'Hello' as large ASCII art"],["echo 'Hi' | figlet","Pipe text to figlet for ASCII art"]],tags:"ascii,fun"},
{cat:"misc",cmd:"fortune",desc:"Random quotes/fortune",detail:"Displays random quotes, jokes, or fortunes. Combine with cowsay for entertainment: fortune | cowsay.",ex:[["fortune","Display a random quote or fortune"],["fortune -o","Show potentially offensive fortunes"],["fortune | cowsay","Combine fortune with cowsay for fun"]],tags:"fun"},
{cat:"misc",cmd:"yes",desc:"Output a string repeatedly",detail:"Repeats a string forever until killed. Commonly piped to auto-answer 'y' to interactive prompts.",ex:[["yes | apt-get install package","Auto-answer 'y' to all install prompts"],["yes 'y' | command","Send 'y' repeatedly to command's input"]],tags:"auto-confirm"},
{cat:"misc",cmd:"seq",desc:"Print a sequence of numbers",detail:"Generates number sequences. From-to, with increment step, -w zero-padded. Useful in for loops.",ex:[["seq 1 10","Print numbers 1 through 10"],["seq 1 2 20","Print odd numbers 1,3,5,...,19 (step 2)"],["seq -w 01 10","Print zero-padded: 01, 02, ..., 10"]],tags:"sequence,numbers"},
{cat:"misc",cmd:"shuf",desc:"Generate random permutations",detail:"Shuffles input lines randomly. -i generate from range, -n count, -r repeat. Useful for random selection.",ex:[["shuf file.txt","Randomly shuffle lines of file.txt"],["shuf -i 1-100 -n 5","Pick 5 random numbers from 1 to 100"],["echo 'a b c' | tr ' ' '\\n' | shuf","Shuffle words in a string"]],tags:"random,shuffle"},
{cat:"misc",cmd:"factor",desc:"Prime factorization",detail:"Returns prime factors of given numbers. Quick number theory tool.",ex:[["factor 42","Show prime factors of 42 (2, 3, 7)"],["factor 100","Show prime factors of 100 (2, 2, 5, 5)"]],tags:"math,prime"},
{cat:"misc",cmd:"base64",desc:"Base64 encode/decode",detail:"Encodes/decodes Base64. -d decode. Common for encoding binary data as text, API tokens, data URLs.",ex:[["echo 'hello' | base64","Encode 'hello' as Base64 string"],["echo 'aGVsbG8K' | base64 -d","Decode Base64 string back to text"]],tags:"encode"},
{cat:"misc",cmd:"md5sum",desc:"Compute MD5 checksums",detail:"Generates MD5 hash of files. Used to verify file integrity. -c checks against saved checksums. Note: MD5 is not cryptographically secure.",ex:[["md5sum file.txt","Generate MD5 hash of file.txt"],["md5sum *.iso > checksums.md5","Save checksums of all ISO files to file"]],tags:"hash,checksum"},
{cat:"misc",cmd:"sha256sum",desc:"Compute SHA256 checksums",detail:"Generates SHA256 hash of files. More secure than MD5. -c verifies against saved checksums. Used for download verification.",ex:[["sha256sum file.txt","Generate SHA256 hash of file.txt"],["sha256sum -c checksums.sha256","Verify files against saved checksums"]],tags:"hash,checksum"},
{cat:"misc",cmd:"mktemp",desc:"Create temporary file or directory",detail:"Creates unique temp files/dirs safely. -d for directory. Returns the path. Auto-removed on reboot.",ex:[["tmpfile=$(mktemp)","Create a unique temp file, store path in variable"],["tmpdir=$(mktemp -d)","Create a unique temp directory"]],tags:"temp"},
{cat:"misc",cmd:"sleep",desc:"Delay for a specified time",detail:"Pauses execution for specified duration. Supports s (seconds), m (minutes), h (hours), d (days). Used in scripts and loops.",ex:[["sleep 5","Pause for 5 seconds"],["sleep 2m","Pause for 2 minutes"],["sleep 1h 30m","Pause for 1 hour and 30 minutes"]],tags:"delay"},
{cat:"misc",cmd:"timeout",desc:"Run command with time limit",detail:"Runs a command and kills it if it exceeds the time limit. Useful in scripts to prevent hanging. Supports s/m/h/d suffixes.",ex:[["timeout 10 ping google.com","Run ping for max 10 seconds then kill"],["timeout 5s ./script.sh","Run script.sh, kill if it takes longer than 5 seconds"]],tags:"limit,time"},
];

